#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 100
int top = -1;
long stack[MAX_SIZE];
void push(long value) {
    if (top < MAX_SIZE - 1) {
        stack[++top] = value;
    }
}
long pop() {
    if (top >= 0) {
        return stack[top--];
    }
    return 0;
}
int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <postfix_expression>\n", argv[0]);
        return 1;
    }
    for (int i = 1; i < argc; i++) {
        char *token = argv[i];
        if (token[0] == '+' || token[0] == '-' || token[0] == '*' || token[0] == '/') {
            long operand2 = pop();
            long operand1 = pop();
            long result;
            switch (token[0]) {
                case '+':
                    result = operand1 + operand2;
                    break;
                case '-':
                    result = operand1 - operand2;
                    break;
                case '*':
                    result = operand1 * operand2;
                    break;
                case '/':
                    result = operand1 / operand2;
                    break;
            }
            push(result);
        }
        else {
            char *endptr;
            long value = strtol(token, &endptr, 10);
            if (*endptr != '\0') {
                printf("Invalid token: %s\n", token);
                return 1;
            }
            push(value);
        }
    }
    if (top != 0) {
        printf("Invalid postfix expression\n");
        return 1;
    }
    printf("%ld\n", pop());
    return 0;
}
